code.source:
#include <stdio.h>
#include <string.h>

int main() {
    char name[30];
    char address[50];

    printf("Enter your name: ");
    scanf("%29s", name);
    printf("scanf got: %s\n", name);

    while (getchar() != '\n');

    printf("Enter your address: ");
    fgets(address, sizeof(address), stdin);
    address[strcspn(address, "\n")] = '\0';
    printf("fgets got: %s\n", address);
    return 0;
}

